<div class="page-title"><div><em>PAYMENTS</em><h1>Beneficiaries</h1><p>Manage the people and businesses you pay.</p></div><button class="btn" data-modal="beneficiary-modal">+ Add beneficiary</button></div><section class="panel list"><?php foreach($beneficiaries as $b):?><div class="list-row"><span class="avatar"><?=initials($b['name'])?></span><div><b><?=html_escape($b['name'])?></b><small><?=html_escape($b['bank_name'])?> · <?=html_escape($b['account_number'])?></small></div><span class="<?=status_class($b['status'])?>"><?=ucfirst($b['status'])?></span><a class="outline" href="<?=site_url('transfer')?>">Send money</a></div><?php endforeach?></section><dialog id="beneficiary-modal"><div class="dialog-head"><h2>Add beneficiary</h2><button data-close>×</button></div><?=form_open('beneficiaries')?><label>Name</label><input name="name" required><label>Account number</label><input name="account_number" required><label>Bank name</label><input name="bank_name" required><label>Routing / SWIFT code</label><input name="routing_code"><button class="btn wide">Add beneficiary</button></form></dialog>
